SELECT sm.sm_ship_mode_id, sm.sm_carrier, d.d_year, d.d_quarter_name, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_fee) AS total_fee, AVG(cr.cr_return_tax) AS avg_return_tax, ROW_NUMBER() OVER (PARTITION BY d.d_year ORDER BY SUM(cr.cr_return_amount) DESC) AS amount_rank FROM catalog_returns cr JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk WHERE sm.sm_type = 'AIR' GROUP BY sm.sm_ship_mode_id, sm.sm_carrier, d.d_year, d.d_quarter_name ORDER BY d.d_year, amount_rank
